  USING (((is_available_for_custom_formulation = true) AND (regulatory_status = ANY (ARRAY['pre_1994_dietary_ingredient'::text, 'gras_affirmed'::text])) AND (EXISTS ( SELECT 1
   FROM (level_4_enrollments le
